(function(){var a=document.getElementById("v5-lib-audio"),cur=null;function reset(b){if(b){b.classList.remove("is-on")}}document.querySelectorAll(".v5-lib-play").forEach(function(b){b.addEventListener("click",function(){if(cur===b&&!a.paused){a.pause();reset(b);return}reset(cur);cur=b;a.src=b.dataset.src;a.play();b.classList.add("is-on")})});a.addEventListener("ended",function(){reset(cur)})})();
